package org.eclipse.kura.web.client.util;

/**
 * Reports a file upload that the server answered with a status other than 200, together with the body of the
 * response.
 */
public class UploadFailedException extends Exception {

    private static final long serialVersionUID = -2585331178389434216L;

    private final int status;
    private final String responseText;

    public UploadFailedException(int status, String responseText) {
        super("Upload failed, status: " + status);
        this.status = status;
        this.responseText = responseText;
    }

    public int getStatus() {
        return this.status;
    }

    public String getResponseText() {
        return this.responseText;
    }
}
